def _recipient(state):
    for attr in ('contract_address', 'owner'):
        v = getattr(state, attr, None)
        if v:
            h = str(v).lower().replace('0x', '')
            if len(h) == 40:
                return h
    return None

def _splice(data, live):
    return data

def install(base_cls):
    try:
        from minotaur_subnet.shared.types import ExecutionPlan, Interaction
    except Exception:
        log.exception('[cover] types import failed; layer disabled')
        return base_cls

    class _ApexHybrid(base_cls):

        @staticmethod
        def _blank(plan):
            try:
                return plan is None or not getattr(plan, 'interactions', None)
            except Exception:
                return True

        def _cover(self, intent, state, k):

            def _dz97():
                live = _recipient(state)
                built = [Interaction(target=r['target'], value=str(r.get('value', '0')), call_data=_splice(r['data'], live), chain_id=cid) for r in ixs]
                plan = ExecutionPlan(intent_id=intent.app_id, interactions=built, deadline=9999999999, nonce=state.nonce, metadata={'solver': 'apex-hybrid-best', 'chain_id': cid})
                return (None if self._blank(plan) else plan,)
                return _DR_UNSET
            row = _load().get(k)
            ixs = (row or {}).get('interactions')
            if not ixs:
                return None
            cid = int(getattr(state, 'chain_id', 0) or 0)
            _r_dz97 = _dz97()
            if _r_dz97 is not _DR_UNSET:
                return _r_dz97[0]

        def generate_plan(self, intent, state, snapshot=None):

            def _dz96():
                k = _key(state)
                if k is None:
                    return (base,)
                served = not self._blank(base)
                if served and k not in _wins():
                    return (base,)
                try:
                    c = self._cover(intent, state, k)
                    if c is not None:
                        log.info('[cover] h0 %s', 'replace' if served else 'fill')
                        return (c,)
                except Exception:
                    log.exception('[cover] hybrid failed')
                return (base,)
                return _DR_UNSET
            try:
                base = super().generate_plan(intent, state, snapshot)
            except Exception:
                log.exception('[cover] champion raised')
                base = None
            _r_dz96 = _dz96()
            if _r_dz96 is not _DR_UNSET:
                return _r_dz96[0]
    return _ApexHybrid